-- ============================================================
--  Experiencias de clase: Curso de Registro Sanitario de Medicamentos Biológicos
--
--  Generado por scripts/generar-experiencias-catalogo.mjs a partir del
--  resumen de cada clase, los enlaces verificados y el material de
--  evaluación de contenido/aula/catalogo. No editar a mano.
--
--  34 clases. No toca cursos con experiencia escrita a
--  mano ni clases que ya tenían texto largo aprobado.
-- ============================================================

DO $curso$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Curso de Registro Sanitario de Medicamentos Biológicos$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Curso de Registro Sanitario de Medicamentos Biológicos$t$;
    RETURN;
  END IF;

  -- 01. Introducción al curso: por qué los biológicos tienen un régimen propio
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Introducción al curso: por qué los biológicos tienen un régimen propio$t$
     AND m.title = $u$Unidad 1. Fundamentos de los medicamentos biológicos y su marco normativo$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Introducción al curso: por qué los biológicos tienen un régimen propio$t$, $u$Unidad 1. Fundamentos de los medicamentos biológicos y su marco normativo$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Introducción al curso: por qué los biológicos tienen un régimen propio","texto":"En un titular de registros sanitarios que opera en Colombia, el INVIMA requiere información adicional y el plazo empieza a correr. Lo que está en juego es el criterio de introducción al curso: por qué los biológicos tienen un régimen propio. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar introducción al curso: por qué los biológicos tienen un régimen propio con tus propias palabras y reconocer por qué importa en curso de Registro Sanitario de Medicamentos Biológicos.","Relacionar introducción al curso: por qué los biológicos tienen un régimen propio con unidad 1. Fundamentos de los medicamentos biológicos y su marco normativo y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar introducción al curso: por qué los biológicos tienen un régimen propio y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Resume el alcance del curso y por qué los biológicos se evalúan bajo el Decreto 1782 de 2014 además del régimen base del Decreto 677 de 1995."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, introducción al curso: por qué los biológicos tienen un régimen propio aparece en medio de una decisión que no admite improvisación: el INVIMA requiere información adicional y el plazo empieza a correr. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos de los medicamentos biológicos y su marco normativo. El objetivo del curso es claro: Que el Químico Farmacéutico planee, prepare y mantenga el registro sanitario de un medicamento biológico ante el INVIMA, aplicando el Decreto 1782 de 2014, sus guías técnicas, los estándares ICH de calidad y los requisitos de BPM y cadena de frío. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Resume el alcance del curso y por qué los biológicos se evalúan bajo el Decreto 1782 de 2014 además del régimen base del Decreto 677 de 1995.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en registro sanitario y en expediente, no en la intuición.","La clase pertenece a unidad 1. Fundamentos de los medicamentos biológicos y su marco normativo y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Tabla de clasificación con fundamento normativo.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar introducción al curso: por qué los biológicos tienen un régimen propio, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Revisa los artículos 2, 3 y 7 a 9 del Decreto 1782 de 2014. Evidencia que debe quedar: Registro del paso.","Decide si cada producto está dentro del ámbito. Evidencia que debe quedar: Registro del paso.","Identifica la ruta probable (completa, comparabilidad o abreviada) y sus condiciones. Evidencia que debe quedar: Registro del paso.","Señala la sigla de registro (MB o MBT) cuando aplique. Evidencia que debe quedar: Registro del paso.","Identifica qué información común (art. 6) deberá presentar cada uno. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar introducción al curso: por qué los biológicos tienen un régimen propio en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Introducción al curso: por qué los biológicos tienen un régimen propio»?","respuesta":"Resume el alcance del curso y por qué los biológicos se evalúan bajo el Decreto 1782 de 2014 además del régimen base del Decreto 677 de 1995."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Tabla de clasificación con fundamento normativo.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Introducción al curso: por qué los biológicos tienen un régimen propio se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos de los medicamentos biológicos y su marco normativo.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"¿Qué son los Medicamentos Biológicos y Biosimilares?","url":"https://www.youtube.com/watch?v=Cq2diDJQSgo"},{"cita":"Diplomado en Asuntos regulatorios sobre medicamentos biológicos y de síntesis química (contenidos y módulos). Universidad El Bosque (ES)","url":"https://www.unbosque.edu.co/sites/default/files/2025-07/Diplomado%20en%20Asuntos%20regulatorios%20sobre%20medicamentos%20biologicos%20y%20de%20sintesis%20quimica.pdf"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente introducción al curso: por qué los biológicos tienen un régimen propio en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de introducción al curso: por qué los biológicos tienen un régimen propio"}],"keywords":["curso","registro","sanitario","medicamentos","biológicos","introducción","tienen","régimen","propio","unidad","fundamentos","marco"],"mapa":{"centro":"Introducción al curso: por qué los biológicos tienen un régimen propio","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios — productos especiales","Unidad 1. Fundamentos de los medicamentos biológicos y su marco normativo","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Clasificación normativa de un portafolio biológico","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Revisa los artículos 2, 3 y 7 a 9 del Decreto 1782 de 2014.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Decide si cada producto está dentro del ámbito.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Identifica la ruta probable (completa, comparabilidad o abreviada) y sus condiciones.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Señala la sigla de registro (MB o MBT) cuando aplique.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Identifica qué información común (art. 6) deberá presentar cada uno.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Clasificación normativa de un portafolio biológico","contexto":"BioAndes (ficticia) prepara cinco solicitudes (datos simulados): (1) un anticuerpo monoclonal innovador con estudios propios; (2) un biosimilar de filgrastim; (3) una eritropoyetina con amplia experiencia clínica que se presentaría con información publicada; (4) un alérgeno para pruebas cutáneas; (5) una vacuna importada.","pregunta":"¿Qué decisión demuestra que entendiste introducción al curso: por qué los biológicos tienen un régimen propio?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 02. Definición de medicamento biológico y diferencias con la síntesis química
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Definición de medicamento biológico y diferencias con la síntesis química$t$
     AND m.title = $u$Unidad 1. Fundamentos de los medicamentos biológicos y su marco normativo$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Definición de medicamento biológico y diferencias con la síntesis química$t$, $u$Unidad 1. Fundamentos de los medicamentos biológicos y su marco normativo$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Definición de medicamento biológico y diferencias con la síntesis química","texto":"En un titular de registros sanitarios que opera en Colombia, el titular cambia de fabricante y no sabe si eso exige modificar la autorización. Lo que está en juego es el criterio de definición de medicamento biológico y diferencias con la síntesis química. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar definición de medicamento biológico y diferencias con la síntesis química con tus propias palabras y reconocer por qué importa en curso de Registro Sanitario de Medicamentos Biológicos.","Relacionar definición de medicamento biológico y diferencias con la síntesis química con unidad 1. Fundamentos de los medicamentos biológicos y su marco normativo y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar definición de medicamento biológico y diferencias con la síntesis química y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Describe la definición legal del Decreto 1782 (biológico y biotecnológico) y las diferencias de tamaño, complejidad, variabilidad y dependencia del proceso frente a moléculas pequeñas."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, definición de medicamento biológico y diferencias con la síntesis química aparece en medio de una decisión que no admite improvisación: el titular cambia de fabricante y no sabe si eso exige modificar la autorización. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos de los medicamentos biológicos y su marco normativo. El objetivo del curso es claro: Que el Químico Farmacéutico planee, prepare y mantenga el registro sanitario de un medicamento biológico ante el INVIMA, aplicando el Decreto 1782 de 2014, sus guías técnicas, los estándares ICH de calidad y los requisitos de BPM y cadena de frío. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Describe la definición legal del Decreto 1782 (biológico y biotecnológico) y las diferencias de tamaño, complejidad, variabilidad y dependencia del proceso frente a moléculas pequeñas.","Una pregunta que se usa para comprobar esta clase es: «Según el artículo 3 del Decreto 1782 de 2014, ¿cuándo un medicamento biológico se denomina biotecnológico?» La respuesta correcta se apoya en lo siguiente: El artículo 3 define el medicamento biológico como el derivado de organismos o células vivas o sus partes, y denomina biotecnológicos a los obtenidos por ADN recombinante, hibridoma o transgénesis. El artículo 19 agrega las siglas MB o MBT al número de registro. La fuente citada es: Decreto 1782 de 2014, arts. 3 y 19.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Fundamentos de los medicamentos biológicos y su marco normativo y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Tabla de clasificación con fundamento normativo.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar definición de medicamento biológico y diferencias con la síntesis química, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Revisa los artículos 2, 3 y 7 a 9 del Decreto 1782 de 2014. Evidencia que debe quedar: Registro del paso.","Decide si cada producto está dentro del ámbito. Evidencia que debe quedar: Registro del paso.","Identifica la ruta probable (completa, comparabilidad o abreviada) y sus condiciones. Evidencia que debe quedar: Registro del paso.","Señala la sigla de registro (MB o MBT) cuando aplique. Evidencia que debe quedar: Registro del paso.","Identifica qué información común (art. 6) deberá presentar cada uno. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar definición de medicamento biológico y diferencias con la síntesis química en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Definición de medicamento biológico y diferencias con la síntesis química»?","respuesta":"Describe la definición legal del Decreto 1782 (biológico y biotecnológico) y las diferencias de tamaño, complejidad, variabilidad y dependencia del proceso frente a moléculas pequeñas."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Tabla de clasificación con fundamento normativo.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Definición de medicamento biológico y diferencias con la síntesis química se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos de los medicamentos biológicos y su marco normativo.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"¿Qué son los Medicamentos Biológicos y Biosimilares?","url":"https://www.youtube.com/watch?v=Cq2diDJQSgo"},{"cita":"[Página web] Decreto 1782 de 2014 – Evaluación farmacológica y farmacéutica de medicamentos biológicos (texto compilado). INVIMA – Normograma (ES)","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/decreto_1782_2014.htm"},{"cita":"[Página web] Acerca de los medicamentos biológicos (inmunológicos, hemoderivados, biotecnológicos, terapias avanzadas). Portal del Medicamento – Junta de Castilla y León / CADIME (ES)","url":"https://www.saludcastillayleon.es/portalmedicamento/es/noticias-destacados/noticias/acerca-medicamentos-biologicos"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente definición de medicamento biológico y diferencias con la síntesis química en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de definición de medicamento biológico y diferencias con la síntesis química"}],"keywords":["curso","registro","sanitario","medicamentos","biológicos","definición","medicamento","biológico","diferencias","síntesis","química","unidad"],"mapa":{"centro":"Definición de medicamento biológico y diferencias con la síntesis química","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios — productos especiales","Unidad 1. Fundamentos de los medicamentos biológicos y su marco normativo","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Clasificación normativa de un portafolio biológico","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Revisa los artículos 2, 3 y 7 a 9 del Decreto 1782 de 2014.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Decide si cada producto está dentro del ámbito.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Identifica la ruta probable (completa, comparabilidad o abreviada) y sus condiciones.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Señala la sigla de registro (MB o MBT) cuando aplique.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Identifica qué información común (art. 6) deberá presentar cada uno.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Definición de medicamento biológico y diferencias con la síntesis química","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 1. Fundamentos de los medicamentos biológicos y su marco normativo: BioAndes (ficticia) prepara cinco solicitudes (datos simulados): (1) un anticuerpo monoclonal innovador con estudios propios; (2) un biosimilar de filgrastim; (3) una eritropoyetina con amplia experiencia clínica que se presentaría con información publicada; (4) un alérgeno para pruebas cutáneas; (5) una vacuna importada. La pregunta que decide esta clase es: Según el artículo 3 del Decreto 1782 de 2014, ¿cuándo un medicamento biológico se denomina biotecnológico?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Cuando se obtiene por ADN recombinante, hibridoma o transgénesis.","correcta":true,"retro":"Correcto. Lleva la sigla MBT en el registro."},{"texto":"Cuando se fabrica en un laboratorio con certificado de BPM vigente y equipos automatizados.","correcta":false,"retro":"La certificación no define la categoría."},{"texto":"Cuando se administra por vía intravenosa en hospitales de alta complejidad.","correcta":false,"retro":"La vía de administración no define la categoría."},{"texto":"Cuando contiene más de un principio activo de origen vegetal o animal en su fórmula.","correcta":false,"retro":"No es la definición del decreto."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 03. Proteínas recombinantes y anticuerpos monoclonales
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Proteínas recombinantes y anticuerpos monoclonales$t$
     AND m.title = $u$Unidad 1. Fundamentos de los medicamentos biológicos y su marco normativo$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Proteínas recombinantes y anticuerpos monoclonales$t$, $u$Unidad 1. Fundamentos de los medicamentos biológicos y su marco normativo$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Proteínas recombinantes y anticuerpos monoclonales","texto":"En un titular de registros sanitarios que opera en Colombia, el INVIMA requiere información adicional y el plazo empieza a correr. Lo que está en juego es el criterio de proteínas recombinantes y anticuerpos monoclonales. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar proteínas recombinantes y anticuerpos monoclonales con tus propias palabras y reconocer por qué importa en curso de Registro Sanitario de Medicamentos Biológicos.","Relacionar proteínas recombinantes y anticuerpos monoclonales con unidad 1. Fundamentos de los medicamentos biológicos y su marco normativo y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar proteínas recombinantes y anticuerpos monoclonales y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Describe las principales clases biotecnológicas (proteínas recombinantes, anticuerpos monoclonales, proteínas de fusión) y su nomenclatura (-mab, -cept)."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, proteínas recombinantes y anticuerpos monoclonales aparece en medio de una decisión que no admite improvisación: el INVIMA requiere información adicional y el plazo empieza a correr. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos de los medicamentos biológicos y su marco normativo. El objetivo del curso es claro: Que el Químico Farmacéutico planee, prepare y mantenga el registro sanitario de un medicamento biológico ante el INVIMA, aplicando el Decreto 1782 de 2014, sus guías técnicas, los estándares ICH de calidad y los requisitos de BPM y cadena de frío. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Describe las principales clases biotecnológicas (proteínas recombinantes, anticuerpos monoclonales, proteínas de fusión) y su nomenclatura (-mab, -cept).","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en registro sanitario y en expediente, no en la intuición.","La clase pertenece a unidad 1. Fundamentos de los medicamentos biológicos y su marco normativo y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Tabla de clasificación con fundamento normativo.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar proteínas recombinantes y anticuerpos monoclonales, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Revisa los artículos 2, 3 y 7 a 9 del Decreto 1782 de 2014. Evidencia que debe quedar: Registro del paso.","Decide si cada producto está dentro del ámbito. Evidencia que debe quedar: Registro del paso.","Identifica la ruta probable (completa, comparabilidad o abreviada) y sus condiciones. Evidencia que debe quedar: Registro del paso.","Señala la sigla de registro (MB o MBT) cuando aplique. Evidencia que debe quedar: Registro del paso.","Identifica qué información común (art. 6) deberá presentar cada uno. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar proteínas recombinantes y anticuerpos monoclonales en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Proteínas recombinantes y anticuerpos monoclonales»?","respuesta":"Describe las principales clases biotecnológicas (proteínas recombinantes, anticuerpos monoclonales, proteínas de fusión) y su nomenclatura (-mab, -cept)."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Tabla de clasificación con fundamento normativo.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Proteínas recombinantes y anticuerpos monoclonales s