    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 13. Caso práctico: ruta y solicitud de un anticuerpo monoclonal nuevo
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso práctico: ruta y solicitud de un anticuerpo monoclonal nuevo$t$
     AND m.title = $u$Unidad 2. Decreto 1782 de 2014: rutas y evaluación farmacológica$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Caso práctico: ruta y solicitud de un anticuerpo monoclonal nuevo$t$, $u$Unidad 2. Decreto 1782 de 2014: rutas y evaluación farmacológica$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Caso práctico: ruta y solicitud de un anticuerpo monoclonal nuevo","texto":"En un titular de registros sanitarios que opera en Colombia, el titular cambia de fabricante y no sabe si eso exige modificar la autorización. Lo que está en juego es el criterio de caso práctico: ruta y solicitud de un anticuerpo monoclonal nuevo. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar caso práctico: ruta y solicitud de un anticuerpo monoclonal nuevo con tus propias palabras y reconocer por qué importa en curso de Registro Sanitario de Medicamentos Biológicos.","Relacionar caso práctico: ruta y solicitud de un anticuerpo monoclonal nuevo con unidad 2. Decreto 1782 de 2014: rutas y evaluación farmacológica y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar caso práctico: ruta y solicitud de un anticuerpo monoclonal nuevo y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Ejecuta la selección de ruta y la planeación completa de la solicitud de evaluación farmacológica y registro de un anticuerpo innovador. ejecutar la selección de ruta y la planeación de la solicitud de evaluación farmacológica y registro sanitario de un anticuerpo monoclonal nuevo en Colombia. el Decreto 1782 de 2014 (art. 5) establece tres rutas con el mismo estándar de evaluación: expediente completo (art. 7), comparabilidad (art. 8) y ruta abreviada de comparabilidad (art. 9). Un anticuerpo innovador, sin producto de referencia,…"},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, caso práctico: ruta y solicitud de un anticuerpo monoclonal nuevo aparece en medio de una decisión que no admite improvisación: el titular cambia de fabricante y no sabe si eso exige modificar la autorización. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 2. Decreto 1782 de 2014: rutas y evaluación farmacológica. El objetivo del curso es claro: Que el Químico Farmacéutico planee, prepare y mantenga el registro sanitario de un medicamento biológico ante el INVIMA, aplicando el Decreto 1782 de 2014, sus guías técnicas, los estándares ICH de calidad y los requisitos de BPM y cadena de frío. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Ejecuta la selección de ruta y la planeación completa de la solicitud de evaluación farmacológica y registro de un anticuerpo innovador. ejecutar la selección de ruta y la planeación de la solicitud de evaluación farmacológica y registro sanitario de un anticuerpo monoclonal nuevo en Colombia. el Decreto 1782 de 2014 (art. 5) establece tres rutas con el mismo estándar de evaluación: expediente completo (art. 7), comparabilidad (art. 8) y ruta abreviada de comparabilidad (art. 9). Un anticuerpo innovador, sin producto de referencia,…","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en registro sanitario y en expediente, no en la intuición.","La clase pertenece a unidad 2. Decreto 1782 de 2014: rutas y evaluación farmacológica y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Plan de solicitud con ruta, secuencia, riesgos y cronograma.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar caso práctico: ruta y solicitud de un anticuerpo monoclonal nuevo, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Justifica la ruta con el artículo correspondiente. Evidencia que debe quedar: Registro del paso.","Lista la información común del artículo 6 que debe preparar el fabricante. Evidencia que debe quedar: Registro del paso.","Describe la secuencia de evaluaciones (arts. 14 y 15) y sus implicaciones en tiempos. Evidencia que debe quedar: Registro del paso.","Identifica los riesgos (inmunogenicidad, plan de gestión de riesgo, requerimientos de la Sala). Evidencia que debe quedar: Registro del paso.","Propón un cronograma con hitos. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar caso práctico: ruta y solicitud de un anticuerpo monoclonal nuevo en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Caso práctico: ruta y solicitud de un anticuerpo monoclonal nuevo»?","respuesta":"Ejecuta la selección de ruta y la planeación completa de la solicitud de evaluación farmacológica y registro de un anticuerpo innovador. ejecutar la selección de ruta y la planeación de la solicitud de evaluación farmacológica y registro sanitario de un anticuerpo monoclonal nuevo en Colombia. el Decreto 1782 de 2014 (art. 5) establece tres rutas con el mismo estándar de evaluación: expediente completo (art. 7), comparabilidad (art. 8) y ruta abreviada de comparabilidad (art. 9). Un anticuerpo innovador, sin producto de referencia,…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Plan de solicitud con ruta, secuencia, riesgos y cronograma.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Caso práctico: ruta y solicitud de un anticuerpo monoclonal nuevo se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 2. Decreto 1782 de 2014: rutas y evaluación farmacológica.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente caso práctico: ruta y solicitud de un anticuerpo monoclonal nuevo en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de caso práctico: ruta y solicitud de un anticuerpo monoclonal nuevo"}],"keywords":["curso","registro","sanitario","medicamentos","biológicos","práctico","solicitud","anticuerpo","monoclonal","nuevo","unidad","decreto"],"mapa":{"centro":"Caso práctico: ruta y solicitud de un anticuerpo monoclonal nuevo","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios — productos especiales","Unidad 2. Decreto 1782 de 2014: rutas y evaluación farmacológica","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Planeación de la solicitud de un anticuerpo monoclonal nuevo","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Justifica la ruta con el artículo correspondiente.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Lista la información común del artículo 6 que debe preparar el fabricante.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Describe la secuencia de evaluaciones (arts. 14 y 15) y sus implicaciones en tiempos.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Identifica los riesgos (inmunogenicidad, plan de gestión de riesgo, requerimientos de la Sala).","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Propón un cronograma con hitos.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Planeación de la solicitud de un anticuerpo monoclonal nuevo","contexto":"Inmuno Pacífico (ficticia) quiere registrar un anticuerpo monoclonal innovador para artritis reumatoide, fabricado en el exterior, con estudios preclínicos y ensayos clínicos fase I a III propios (datos simulados). La gerencia pide un plan con tiempos y riesgos.","pregunta":"¿Qué decisión demuestra que entendiste caso práctico: ruta y solicitud de un anticuerpo monoclonal nuevo?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
