  -- 14. Introducción a la unidad: las guías que desarrollan el Decreto 1782
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Introducción a la unidad: las guías que desarrollan el Decreto 1782$t$
     AND m.title = $u$Unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo$u$
