    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 16. Evaluación del riesgo inmunogénico y estrategia de ensayos
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Evaluación del riesgo inmunogénico y estrategia de ensayos$t$
     AND m.title = $u$Unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Evaluación del riesgo inmunogénico y estrategia de ensayos$t$, $u$Unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Evaluación del riesgo inmunogénico y estrategia de ensayos","texto":"En un titular de registros sanitarios que opera en Colombia, un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. Lo que está en juego es el criterio de evaluación del riesgo inmunogénico y estrategia de ensayos. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar evaluación del riesgo inmunogénico y estrategia de ensayos con tus propias palabras y reconocer por qué importa en curso de Registro Sanitario de Medicamentos Biológicos.","Relacionar evaluación del riesgo inmunogénico y estrategia de ensayos con unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar evaluación del riesgo inmunogénico y estrategia de ensayos y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Interpreta los factores de producto, paciente y enfermedad y la estrategia escalonada de detección de anticuerpos antifármaco."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, evaluación del riesgo inmunogénico y estrategia de ensayos aparece en medio de una decisión que no admite improvisación: un registro aparece vencido en la consulta pública mientras la empresa lo creía vigente. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo. El objetivo del curso es claro: Que el Químico Farmacéutico planee, prepare y mantenga el registro sanitario de un medicamento biológico ante el INVIMA, aplicando el Decreto 1782 de 2014, sus guías técnicas, los estándares ICH de calidad y los requisitos de BPM y cadena de frío. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Interpreta los factores de producto, paciente y enfermedad y la estrategia escalonada de detección de anticuerpos antifármaco.","Una pregunta que se usa para comprobar esta clase es: «Un paciente desarrolla anticuerpos antifármaco que neutralizan un biológico. ¿Qué análisis es correcto?» La respuesta correcta se apoya en lo siguiente: La inmunogenicidad es la capacidad de un biológico de inducir una respuesta inmune, como anticuerpos antifármaco que pueden neutralizar su efecto o causar eventos adversos. Se evalúa con una estrategia escalonada (tamizaje, confirmación, neutralización) y es información común exigida (art. 6). La fuente citada es: Decreto 1782 de 2014, art. 6; guía de inmunogenicidad del Ministerio.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar evaluación del riesgo inmunogénico y estrategia de ensayos, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Clasificar el producto. Determina la categoría y el régimen aplicable antes de preparar cualquier documento; una clasificación equivocada cambia todo el expediente. Evidencia que debe quedar: Clasificación sustentada.","Verificar el requisito vigente. Consulta la norma y el normograma de la autoridad; confirma que el requisito no fue modificado o derogado. Evidencia que debe quedar: Norma citada y vigente.","Preparar la evidencia. Organiza la información técnica, legal y de calidad que responde a cada requisito, con control de versiones. Evidencia que debe quedar: Expediente indexado.","Radicar y responder. Presenta la solicitud completa y responde los requerimientos dentro del plazo, con argumentos y documentos verificables. Evidencia que debe quedar: Radicado y respuesta.","Mantener la autorización. Gestiona modificaciones, reportes, renovaciones cuando apliquen y cambios en las condiciones aprobadas. Evidencia que debe quedar: Registro actualizado.","Vigilar el entorno. Sigue cambios normativos, alertas y decisiones de la autoridad que puedan afectar el portafolio. Evidencia que debe quedar: Informe de inteligencia regulatoria.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar evaluación del riesgo inmunogénico y estrategia de ensayos en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Evaluación del riesgo inmunogénico y estrategia de ensayos»?","respuesta":"Interpreta los factores de producto, paciente y enfermedad y la estrategia escalonada de detección de anticuerpos antifármaco."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Evaluación del riesgo inmunogénico y estrategia de ensayos se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"ABECÉ sobre inmunogenicidad. Ministerio de Salud y Protección Social (ES)","url":"https://minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/VS/MET/abc-inmunogenicidad.pdf"},{"cita":"[Página web] Resolución 4490 de 2016 – Guía de Evaluación de la Inmunogenicidad para los Medicamentos Biológicos. INVIMA – Normograma (ES)","url":"https://normograma.invima.gov.co/compilacion/docs/resolucion_minsaludps_4490_2016.htm"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente evaluación del riesgo inmunogénico y estrategia de ensayos en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de evaluación del riesgo inmunogénico y estrategia de ensayos"}],"keywords":["curso","registro","sanitario","medicamentos","biológicos","evaluación","riesgo","inmunogénico","estrategia","ensayos","unidad","guías"],"mapa":{"centro":"Evaluación del riesgo inmunogénico y estrategia de ensayos","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios — productos especiales","Unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Clasificar el producto","Verificar el requisito vigente","Preparar la evidencia"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Clasificación sustentada","Norma citada y vigente","Expediente indexado"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se construye y se sostiene un trámite regulatorio","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Clasificar el producto","detalle":"Determina la categoría y el régimen aplicable antes de preparar cualquier documento; una clasificación equivocada cambia todo el expediente.","icono":"Search","evidencia":"Clasificación sustentada"},{"titulo":"Verificar el requisito vigente","detalle":"Consulta la norma y el normograma de la autoridad; confirma que el requisito no fue modificado o derogado.","icono":"ClipboardList","evidencia":"Norma citada y vigente"},{"titulo":"Preparar la evidencia","detalle":"Organiza la información técnica, legal y de calidad que responde a cada requisito, con control de versiones.","icono":"Workflow","evidencia":"Expediente indexado"},{"titulo":"Radicar y responder","detalle":"Presenta la solicitud completa y responde los requerimientos dentro del plazo, con argumentos y documentos verificables.","icono":"FileCheck","evidencia":"Radicado y respuesta"},{"titulo":"Mantener la autorización","detalle":"Gestiona modificaciones, reportes, renovaciones cuando apliquen y cambios en las condiciones aprobadas.","icono":"RefreshCw","evidencia":"Registro actualizado"},{"titulo":"Vigilar el entorno","detalle":"Sigue cambios normativos, alertas y decisiones de la autoridad que puedan afectar el portafolio.","icono":"CheckCircle2","evidencia":"Informe de inteligencia regulatoria"}]},"caso":{"titulo":"Evaluación del riesgo inmunogénico y estrategia de ensayos","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo: una situación que exige documentar la decisión. La pregunta que decide esta clase es: Un paciente desarrolla anticuerpos antifármaco que neutralizan un biológico. ¿Qué análisis es correcto?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"No es relevante, porque los anticuerpos antifármaco no tienen ningún efecto clínico.","correcta":false,"retro":"Pueden reducir la eficacia o causar eventos."},{"texto":"Es un problema exclusivo de los biosimilares, nunca de los productos innovadores.","correcta":false,"retro":"Afecta también a los innovadores."},{"texto":"Indica un error de dispensación, porque los biológicos no generan respuestas inmunes.","correcta":false,"retro":"Los biológicos pueden ser inmunogénicos."},{"texto":"Es inmunogenicidad: puede reducir la eficacia y se evalúa con ensayos escalonados.","correcta":true,"retro":"Correcto. Es parte del art. 6."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 17. Guía de estabilidad de medicamentos biológicos (Res. 3690 de 2016) e ICH Q5C
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Guía de estabilidad de medicamentos biológicos (Res. 3690 de 2016) e ICH Q5C$t$
     AND m.title = $u$Unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Guía de estabilidad de medicamentos biológicos (Res. 3690 de 2016) e ICH Q5C$t$, $u$Unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Guía de estabilidad de medicamentos biológicos (Res. 3690 de 2016) e ICH Q5C","texto":"En un titular de registros sanitarios que opera en Colombia, el INVIMA requiere información adicional y el plazo empieza a correr. Lo que está en juego es el criterio de guía de estabilidad de medicamentos biológicos (Res. 3690 de 2016) e ICH Q5C. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar guía de estabilidad de medicamentos biológicos (Res. 3690 de 2016) e ICH Q5C con tus propias palabras y reconocer por qué importa en curso de Registro Sanitario de Medicamentos Biológicos.","Relacionar guía de estabilidad de medicamentos biológicos (Res. 3690 de 2016) e ICH Q5C con unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar guía de estabilidad de medicamentos biológicos (Res. 3690 de 2016) e ICH Q5C y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Aplica los requisitos de diseño de estudios de estabilidad, indicadores de estabilidad y asignación de vida útil para biológicos."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, guía de estabilidad de medicamentos biológicos (Res. 3690 de 2016) e ICH Q5C aparece en medio de una decisión que no admite improvisación: el INVIMA requiere información adicional y el plazo empieza a correr. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo. El objetivo del curso es claro: Que el Químico Farmacéutico planee, prepare y mantenga el registro sanitario de un medicamento biológico ante el INVIMA, aplicando el Decreto 1782 de 2014, sus guías técnicas, los estándares ICH de calidad y los requisitos de BPM y cadena de frío. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Aplica los requisitos de diseño de estudios de estabilidad, indicadores de estabilidad y asignación de vida útil para biológicos.","Una pregunta que se usa para comprobar esta clase es: «Para un biológico, un titular propone asignar la vida útil con estudios acelerados extrapolados, como en una tableta de síntesis química. ¿Cuál es la mejor valoración?» La respuesta correcta se apoya en lo siguiente: La guía de estabilidad de biológicos (Resolución 3690 de 2016) e ICH Q5C basan la vida útil en datos reales en las condiciones de almacenamiento propuestas, con indicadores como potencia y agregados; la extrapolación de acelerados no se aplica como en síntesis química. La fuente citada es: Resolución 3690 de 2016; ICH Q5C.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar guía de estabilidad de medicamentos biológicos (Res. 3690 de 2016) e ICH Q5C, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Clasificar el producto. Determina la categoría y el régimen aplicable antes de preparar cualquier documento; una clasificación equivocada cambia todo el expediente. Evidencia que debe quedar: Clasificación sustentada.","Verificar el requisito vigente. Consulta la norma y el normograma de la autoridad; confirma que el requisito no fue modificado o derogado. Evidencia que debe quedar: Norma citada y vigente.","Preparar la evidencia. Organiza la información técnica, legal y de calidad que responde a cada requisito, con control de versiones. Evidencia que debe quedar: Expediente indexado.","Radicar y responder. Presenta la solicitud completa y responde los requerimientos dentro del plazo, con argumentos y documentos verificables. Evidencia que debe quedar: Radicado y respuesta.","Mantener la autorización. Gestiona modificaciones, reportes, renovaciones cuando apliquen y cambios en las condiciones aprobadas. Evidencia que debe quedar: Registro actualizado.","Vigilar el entorno. Sigue cambios normativos, alertas y decisiones de la autoridad que puedan afectar el portafolio. Evidencia que debe quedar: Informe de inteligencia regulatoria.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: Un titular ficticio presentó el plan de gestión de riesgo de un biológico hace tres años y nunca lo actualizó (datos simulados). Desde entonces hubo dos señales de seguridad y una nueva indicación aprobada. No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar guía de estabilidad de medicamentos biológicos (Res. 3690 de 2016) e ICH Q5C en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Guía de estabilidad de medicamentos biológicos (Res. 3690 de 2016) e ICH Q5C»?","respuesta":"Aplica los requisitos de diseño de estudios de estabilidad, indicadores de estabilidad y asignación de vida útil para biológicos."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Guía de estabilidad de medicamentos biológicos (Res. 3690 de 2016) e ICH Q5C se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"[Página web] Resolución 3690 de 2016 – Guía de Estabilidad de Medicamentos Biológicos. INVIMA – Normograma (ES)","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_minsaludps_3690_2016.htm"},{"cita":"ICH Q5C – Stability Testing of Biotechnological/Biological Products. EMA / ICH (EN)","url":"https://www.ema.europa.eu/en/documents/scientific-guideline/quality-biotechnological-products-stability-testing-biotechnological/biological-products_en.pdf"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente guía de estabilidad de medicamentos biológicos (Res. 3690 de 2016) e ICH Q5C en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de guía de estabilidad de medicamentos biológicos (Res. 3690 de 2016) e ICH Q5C"}],"keywords":["curso","registro","sanitario","medicamentos","biológicos","estabilidad","unidad","guías","técnicas","inmunogenicidad","gestión","riesgo"],"mapa":{"centro":"Guía de estabilidad de medicamentos biológicos (Res. 3690 de 2016) e ICH Q5C","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios — productos especiales","Unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Clasificar el producto","Verificar el requisito vigente","Preparar la evidencia"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Clasificación sustentada","Norma citada y vigente","Expediente indexado"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se construye y se sostiene un trámite regulatorio","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Clasificar el producto","detalle":"Determina la categoría y el régimen aplicable antes de preparar cualquier documento; una clasificación equivocada cambia todo el expediente.","icono":"Search","evidencia":"Clasificación sustentada"},{"titulo":"Verificar el requisito vigente","detalle":"Consulta la norma y el normograma de la autoridad; confirma que el requisito no fue modificado o derogado.","icono":"ClipboardList","evidencia":"Norma citada y vigente"},{"titulo":"Preparar la evidencia","detalle":"Organiza la información técnica, legal y de calidad que responde a cada requisito, con control de versiones.","icono":"Workflow","evidencia":"Expediente indexado"},{"titulo":"Radicar y responder","detalle":"Presenta la solicitud completa y responde los requerimientos dentro del plazo, con argumentos y documentos verificables.","icono":"FileCheck","evidencia":"Radicado y respuesta"},{"titulo":"Mantener la autorización","detalle":"Gestiona modificaciones, reportes, renovaciones cuando apliquen y cambios en las condiciones aprobadas.","icono":"RefreshCw","evidencia":"Registro actualizado"},{"titulo":"Vigilar el entorno","detalle":"Sigue cambios normativos, alertas y decisiones de la autoridad que puedan afectar el portafolio.","icono":"CheckCircle2","evidencia":"Informe de inteligencia regulatoria"}]},"caso":{"titulo":"Guía de estabilidad de medicamentos biológicos (Res. 3690 de 2016) e ICH Q5C","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo: una situación que exige documentar la decisión. La pregunta que decide esta clase es: Para un biológico, un titular propone asignar la vida útil con estudios acelerados extrapolados, como en una tableta de síntesis química. ¿Cuál es la mejor valoración?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Es adecuado, porque la extrapolación es aceptada igual para todos los medicamentos.","correcta":false,"retro":"Los biológicos tienen requisitos propios."},{"texto":"Es adecuado si el producto se conserva refrigerado durante toda su vida útil.","correcta":false,"retro":"La refrigeración no habilita la extrapolación."},{"texto":"Es inadecuado: en biológicos la vida útil se basa en datos reales en las condiciones propuestas.","correcta":true,"retro":"Correcto. Según la guía de biológicos e ICH Q5C."},{"texto":"Es inadecuado solo porque los biológicos no requieren estudios de estabilidad.","correcta":false,"retro":"Sí los requieren, con su propia guía."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 18. Plan de gestión de riesgo: Resolución 213 de 2022
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Plan de gestión de riesgo: Resolución 213 de 2022$t$
     AND m.title = $u$Unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Plan de gestión de riesgo: Resolución 213 de 2022$t$, $u$Unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Plan de gestión de riesgo: Resolución 213 de 2022","texto":"En un titular de registros sanitarios que opera en Colombia, llega una alerta sanitaria sobre un producto del portafolio y hay que decidir qué hacer. Lo que está en juego es el criterio de plan de gestión de riesgo: Resolución 213 de 2022. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar plan de gestión de riesgo: Resolución 213 de 2022 con tus propias palabras y reconocer por qué importa en curso de Registro Sanitario de Medicamentos Biológicos.","Relacionar plan de gestión de riesgo: Resolución 213 de 2022 con unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar plan de gestión de riesgo: Resolución 213 de 2022 y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Describe la estructura del PGR (especificaciones de seguridad, plan de farmacovigilancia, minimización de riesgos) y a quiénes aplica."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, plan de gestión de riesgo: Resolución 213 de 2022 aparece en medio de una decisión que no admite improvisación: llega una alerta sanitaria sobre un producto del portafolio y hay que decidir qué hacer. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo. El objetivo del curso es claro: Que el Químico Farmacéutico planee, prepare y mantenga el registro sanitario de un medicamento biológico ante el INVIMA, aplicando el Decreto 1782 de 2014, sus guías técnicas, los estándares ICH de calidad y los requisitos de BPM y cadena de frío. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Describe la estructura del PGR (especificaciones de seguridad, plan de farmacovigilancia, minimización de riesgos) y a quiénes aplica.","Una pregunta que se usa para comprobar esta clase es: «¿Qué exige el artículo 24 del Decreto 1782 al titular en materia de farmacovigilancia?» La respuesta correcta se apoya en lo siguiente: El artículo 24 exige al titular implementar un plan de gestión de riesgos y un programa de farmacovigilancia activa, presentar informes periódicos de seguridad y contar con tecnología de señalización que permita identificar el producto en la cadena de distribución. La fuente citada es: Decreto 1782 de 2014, art. 24.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar plan de gestión de riesgo: Resolución 213 de 2022, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Clasificar el producto. Determina la categoría y el régimen aplicable antes de preparar cualquier documento; una clasificación equivocada cambia todo el expediente. Evidencia que debe quedar: Clasificación sustentada.","Verificar el requisito vigente. Consulta la norma y el normograma de la autoridad; confirma que el requisito no fue modificado o derogado. Evidencia que debe quedar: Norma citada y vigente.","Preparar la evidencia. Organiza la información técnica, legal y de calidad que responde a cada requisito, con control de versiones. Evidencia que debe quedar: Expediente indexado.","Radicar y responder. Presenta la solicitud completa y responde los requerimientos dentro del plazo, con argumentos y documentos verificables. Evidencia que debe quedar: Radicado y respuesta.","Mantener la autorización. Gestiona modificaciones, reportes, renovaciones cuando apliquen y cambios en las condiciones aprobadas. Evidencia que debe quedar: Registro actualizado.","Vigilar el entorno. Sigue cambios normativos, alertas y decisiones de la autoridad que puedan afectar el portafolio. Evidencia que debe quedar: Informe de inteligencia regulatoria.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: Un titular ficticio presentó el plan de gestión de riesgo de un biológico hace tres años y nunca lo actualizó (datos simulados). Desde entonces hubo dos señales de seguridad y una nueva indicación aprobada. No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar plan de gestión de riesgo: Resolución 213 de 2022 en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Plan de gestión de riesgo: Resolución 213 de 2022»?","respuesta":"Describe la estructura del PGR (especificaciones de seguridad, plan de farmacovigilancia, minimización de riesgos) y a quiénes aplica."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Plan de gestión de riesgo: Resolución 213 de 2022 se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 3. Guías técnicas: inmunogenicidad, estabilidad y gestión de riesgo.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"[Página web] Resolución 213 de 2022 – Guía para la elaboración de Planes de Gestión de Riesgo de medicamentos de síntesis química con nuevos IFA y medicamentos biológicos. INVIMA – Normograma (ES)","url":"https://normograma.invima.gov.co/compilacion/docs/resolucion_minsaludps_0213_2022.htm"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"htt