  -- 25. Proceso de fabricación upstream y downstream en el dossier
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Proceso de fabricación upstream y downstream en el dossier$t$
     AND m.title = $u$Unidad 4. Calidad de biológicos y Buenas Prácticas de Manufactura$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Proceso de fabricación upstream y downstream en el dossier$t$, $u$Unidad 4. Calidad de biológicos y Buenas Prácticas de Manufactura$u$;
