  -- 03. Resolución 1606 de 2014: lineamientos técnicos para presentar información de vacunas
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Resolución 1606 de 2014: lineamientos técnicos para presentar información de vacunas$t$
     AND m.title = $u$Unidad 1. Las vacunas como medicamentos biológicos: marco regulatorio y plataformas$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
