  -- 16. Marco legal: artículo 25 del Decreto 1782 y Resolución 22392 de 2010
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Marco legal: artículo 25 del Decreto 1782 y Resolución 22392 de 2010$t$
     AND m.title = $u$Unidad 3. Liberación lote a lote, precalificación OMS y PAI$u$
   ORDER BY l.id LIMIT 1;
