  -- 20. Fondo Rotatorio de la OPS: compra conjunta de vacunas
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Fondo Rotatorio de la OPS: compra conjunta de vacunas$t$
     AND m.title = $u$Unidad 3. Liberación lote a lote, precalificación OMS y PAI$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Fondo Rotatorio de la OPS: compra conjunta de vacunas$t$, $u$Unidad 3. Liberación lote a lote, precalificación OMS y PAI$u$;
