  -- 28. Vacunas en situaciones excepcionales: emergencias, donaciones y vitales no disponibles frente a la liberación de lotes
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Vacunas en situaciones excepcionales: emergencias, donaciones y vitales no disponibles frente a la liberación de lotes$t$
     AND m.title = $u$Unidad 4. Autorización sanitaria de uso de emergencia (ASUE): el caso COVID-19$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
