  -- 04. Definiciones y clasificación: PFM, PFT y PFTI
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Definiciones y clasificación: PFM, PFT y PFTI$t$
     AND m.title = $u$Unidad 1. Marco normativo, definiciones y clasificación de los productos fitoterapéuticos$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Definiciones y clasificación: PFM, PFT y PFTI$t$, $u$Unidad 1. Marco normativo, definiciones y clasificación de los productos fitoterapéuticos$u$;
