      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 06. Caso práctico: clasificar cuatro productos con base en plantas
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso práctico: clasificar cuatro productos con base en plantas$t$
     AND m.title = $u$Unidad 1. Marco normativo, definiciones y clasificación de los productos fitoterapéuticos$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Caso práctico: clasificar cuatro productos con base en plantas$t$, $u$Unidad 1. Marco normativo, definiciones y clasificación de los productos fitoterapéuticos$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Caso práctico: clasificar cuatro productos con base en plantas","texto":"En un titular de registros sanitarios que opera en Colombia, mercadeo quiere lanzar una pieza con una indicación que no está en el registro. Lo que está en juego es el criterio de caso práctico: clasificar cuatro productos con base en plantas. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar caso práctico: clasificar cuatro productos con base en plantas con tus propias palabras y reconocer por qué importa en curso de Registro Sanitario de Productos Fitoterapéuticos.","Relacionar caso práctico: clasificar cuatro productos con base en plantas con unidad 1. Marco normativo, definiciones y clasificación de los productos fitoterapéuticos y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar caso práctico: clasificar cuatro productos con base en plantas y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Aplica las definiciones a registros reales del INVIMA (un PFM de venta libre y un PFT tradicional nacional) y a casos de frontera para decidir la categoría y la vía de trámite."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, caso práctico: clasificar cuatro productos con base en plantas aparece en medio de una decisión que no admite improvisación: mercadeo quiere lanzar una pieza con una indicación que no está en el registro. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Marco normativo, definiciones y clasificación de los productos fitoterapéuticos. El objetivo del curso es claro: Capacitar al Químico Farmacéutico para clasificar, documentar, radicar, mantener y renovar registros sanitarios de productos fitoterapéuticos ante el INVIMA, conforme al Decreto 1156 de 2018 y sus normas complementarias vigentes. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Aplica las definiciones a registros reales del INVIMA (un PFM de venta libre y un PFT tradicional nacional) y a casos de frontera para decidir la categoría y la vía de trámite.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en registro sanitario y en expediente, no en la intuición.","La clase pertenece a unidad 1. Marco normativo, definiciones y clasificación de los productos fitoterapéuticos y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Tabla de clasificación con fundamento.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar caso práctico: clasificar cuatro productos con base en plantas, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Revisa los artículos 3, 10, 15 y 20 del Decreto 1156 de 2018. Evidencia que debe quedar: Registro del paso.","Clasifica cada producto (PFM, PFT, PFTI u otro). Evidencia que debe quedar: Registro del paso.","Indica la vía de registro (con evaluación o automático). Evidencia que debe quedar: Registro del paso.","Analiza las formas farmacéuticas permitidas y excluidas. Evidencia que debe quedar: Registro del paso.","Indica dónde verificarías que la planta esté en el listado. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: Una tienda naturista ficticia vende (datos simulados): un té de manzanilla «para la digestión», cápsulas de un extracto estandarizado con indicación definida, un polvo de proteína con extracto de jengibre y una crema de caléndula. El propietario pregunta qué registro necesita cada uno. No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Error: citar una norma derogada Corrección: antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores.","Error: tratar la modificación como un trámite menor Corrección: un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar caso práctico: clasificar cuatro productos con base en plantas en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Caso práctico: clasificar cuatro productos con base en plantas»?","respuesta":"Aplica las definiciones a registros reales del INVIMA (un PFM de venta libre y un PFT tradicional nacional) y a casos de frontera para decidir la categoría y la vía de trámite."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Tabla de clasificación con fundamento.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Caso práctico: clasificar cuatro productos con base en plantas se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Marco normativo, definiciones y clasificación de los productos fitoterapéuticos.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"Resolución INVIMA 2024004537 – Registro sanitario PFM2024-0002953 (Psyllium, preparación farmacéutica con base en plantas, venta libre). INVIMA – Consulta de registros (ES)","url":"https://webservice.invima.gov.co/registros/pdf/16172774_2024004537.pdf"},{"cita":"Resolución INVIMA 2024004297 – Renovación de registro: PFM2010-0001618 pasa a PFT2024-0001618-R1 (asociación boldo, cáscara sagrada, psyllium y sen). INVIMA – Consulta de registros (ES)","url":"https://webservice.invima.gov.co/registros/pdf/16512640_2024004297.pdf"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente caso práctico: clasificar cuatro productos con base en plantas en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de caso práctico: clasificar cuatro productos con base en plantas"}],"keywords":["curso","registro","sanitario","productos","fitoterapéuticos","práctico","clasificar","cuatro","plantas","unidad","marco","normativo"],"mapa":{"centro":"Caso práctico: clasificar cuatro productos con base en plantas","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios — productos especiales","Unidad 1. Marco normativo, definiciones y clasificación de los productos fitoterapéuticos","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Clasificación de cuatro productos con base en plantas","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Revisa los artículos 3, 10, 15 y 20 del Decreto 1156 de 2018.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Clasifica cada producto (PFM, PFT, PFTI u otro).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Indica la vía de registro (con evaluación o automático).","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Analiza las formas farmacéuticas permitidas y excluidas.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Indica dónde verificarías que la planta esté en el listado.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Clasificación de cuatro productos con base en plantas","contexto":"Naturales del Valle (ficticia) evalúa cuatro productos (datos simulados): (1) tableta de extracto de psyllium para el estreñimiento, con estudios de eficacia; (2) tisana nacional de una planta del listado de uso tradicional; (3) cápsulas importadas de una planta con uso tradicional en su país; (4) gotas oftálmicas de un extracto vegetal.","pregunta":"¿Qué decisión demuestra que entendiste caso práctico: clasificar cuatro productos con base en plantas?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
