  -- 07. Introducción a la unidad: la planta como punto de partida del registro
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Introducción a la unidad: la planta como punto de partida del registro$t$
     AND m.title = $u$Unidad 2. Plantas medicinales aceptadas y evaluación farmacológica$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
