  -- 08. El Vademécum de Plantas Medicinales Colombiano (Res. 2834 de 2008)
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$El Vademécum de Plantas Medicinales Colombiano (Res. 2834 de 2008)$t$
     AND m.title = $u$Unidad 2. Plantas medicinales aceptadas y evaluación farmacológica$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$El Vademécum de Plantas Medicinales Colombiano (Res. 2834 de 2008)$t$, $u$Unidad 2. Plantas medicinales aceptadas y evaluación farmacológica$u$;
