  -- 02. Decreto 3554 de 2004 y su modificación por el Decreto 1861 de 2006
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Decreto 3554 de 2004 y su modificación por el Decreto 1861 de 2006$t$
     AND m.title = $u$Unidad 1. Fundamentos y marco normativo de los medicamentos homeopáticos en Colombia$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
