      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 03. Decreto 1737 de 2005 y Decreto 4664 de 2006: magistrales, oficinales y farmacias homeopáticas
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Decreto 1737 de 2005 y Decreto 4664 de 2006: magistrales, oficinales y farmacias homeopáticas$t$
     AND m.title = $u$Unidad 1. Fundamentos y marco normativo de los medicamentos homeopáticos en Colombia$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Decreto 1737 de 2005 y Decreto 4664 de 2006: magistrales, oficinales y farmacias homeopáticas$t$, $u$Unidad 1. Fundamentos y marco normativo de los medicamentos homeopáticos en Colombia$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Decreto 1737 de 2005 y Decreto 4664 de 2006: magistrales, oficinales y farmacias homeopáticas","texto":"En un titular de registros sanitarios que opera en Colombia, mercadeo quiere lanzar una pieza con una indicación que no está en el registro. Lo que está en juego es el criterio de decreto 1737 de 2005 y Decreto 4664 de 2006: magistrales, oficinales y farmacias homeopáticas. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar decreto 1737 de 2005 y Decreto 4664 de 2006: magistrales, oficinales y farmacias homeopáticas con tus propias palabras y reconocer por qué importa en curso de Regulación de Medicamentos Homeopáticos.","Relacionar decreto 1737 de 2005 y Decreto 4664 de 2006: magistrales, oficinales y farmacias homeopáticas con unidad 1. Fundamentos y marco normativo de los medicamentos homeopáticos en Colombia y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar decreto 1737 de 2005 y Decreto 4664 de 2006: magistrales, oficinales y farmacias homeopáticas y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Reconoce qué regula el Decreto 1737/2005, qué derogó del 3554 y la excepción para médicos de medicina alternativa del Decreto 4664/2006."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, decreto 1737 de 2005 y Decreto 4664 de 2006: magistrales, oficinales y farmacias homeopáticas aparece en medio de una decisión que no admite improvisación: mercadeo quiere lanzar una pieza con una indicación que no está en el registro. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos y marco normativo de los medicamentos homeopáticos en Colombia. El objetivo del curso es claro: Que el químico farmacéutico clasifique, registre, mantenga y comunique medicamentos homeopáticos en Colombia conforme a la normativa vigente (Decretos 3554/2004, 1737/2005, 1861/2006, 334/2022 y 1474/2023; Resoluciones 4594/2007, 3665/2009 y 1896/2023), con criterio técnico y ético. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Reconoce qué regula el Decreto 1737/2005, qué derogó del 3554 y la excepción para médicos de medicina alternativa del Decreto 4664/2006.","Una pregunta que se usa para comprobar esta clase es: «Una farmacia homeopática prepara un medicamento para un paciente según la fórmula de su médico. ¿Qué análisis es correcto sobre su régimen?» La respuesta correcta se apoya en lo siguiente: El Decreto 1737 de 2005 regula la preparación, distribución, dispensación y comercialización de medicamentos homeopáticos magistrales y oficinales y las farmacias homeopáticas; derogó del Decreto 3554 la definición de farmacia homeopática y de magistral. Los magistrales se preparan para un paciente con fórmula y no requieren registro. La fuente citada es: Decreto 1737 de 2005; Decreto 3554 de 2004, art. 2 (nota de vigencia).. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Fundamentos y marco normativo de los medicamentos homeopáticos en Colombia y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Tabla de clasificación con trámite y riesgos.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar decreto 1737 de 2005 y Decreto 4664 de 2006: magistrales, oficinales y farmacias homeopáticas, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Clasifica cada producto (simple, complejo, magistral u otro). Evidencia que debe quedar: Registro del paso.","Indica si se agrupa bajo un solo registro por cepa (art. 24). Evidencia que debe quedar: Registro del paso.","Indica qué evaluaciones exige cada uno (arts. 25 a 30). Evidencia que debe quedar: Registro del paso.","Analiza el producto con cepa no farmacopeica. Evidencia que debe quedar: Registro del paso.","Resume los riesgos de cada producto. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: En una clase ficticia, un estudiante afirma que los homeopáticos «no deberían regularse porque son agua» y otro que «deberían evaluarse como cualquier medicamento» (datos simulados). No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar decreto 1737 de 2005 y Decreto 4664 de 2006: magistrales, oficinales y farmacias homeopáticas en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Decreto 1737 de 2005 y Decreto 4664 de 2006: magistrales, oficinales y farmacias homeopáticas»?","respuesta":"Reconoce qué regula el Decreto 1737/2005, qué derogó del 3554 y la excepción para médicos de medicina alternativa del Decreto 4664/2006."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Tabla de clasificación con trámite y riesgos.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Decreto 1737 de 2005 y Decreto 4664 de 2006: magistrales, oficinales y farmacias homeopáticas se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos y marco normativo de los medicamentos homeopáticos en Colombia.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"[Página web] Decreto 1737 de 2005 – Preparación, distribución, dispensación, comercialización, etiquetado, rotulado y empaque de medicamentos homeopáticos magistrales y oficinales. Normograma INVIMA (ES)","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/decreto_1737_2005.htm"},{"cita":"Decreto 1737 de 2005 (PDF). INVIMA (ES)","url":"https://www.invima.gov.co/invima_website/static/attachments/medicamentos_medicamentos_homeopaticos_fitoterapicos_suplementos/Decreto-1737-de-2005.pdf"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente decreto 1737 de 2005 y Decreto 4664 de 2006: magistrales, oficinales y farmacias homeopáticas en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de decreto 1737 de 2005 y Decreto 4664 de 2006: magistrales, oficinales y farmacias homeopáticas"}],"keywords":["curso","regulación","medicamentos","homeopáticos","decreto","magistrales","oficinales","farmacias","homeopáticas","unidad","fundamentos","marco"],"mapa":{"centro":"Decreto 1737 de 2005 y Decreto 4664 de 2006: magistrales, oficinales y farmacias homeopáticas","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios — productos especiales","Unidad 1. Fundamentos y marco normativo de los medicamentos homeopáticos en Colombia","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Clasificación del portafolio de un laboratorio homeopático","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Clasifica cada producto (simple, complejo, magistral u otro).","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Indica si se agrupa bajo un solo registro por cepa (art. 24).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Indica qué evaluaciones exige cada uno (arts. 25 a 30).","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Analiza el producto con cepa no farmacopeica.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Resume los riesgos de cada producto.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Decreto 1737 de 2005 y Decreto 4664 de 2006: magistrales, oficinales y farmacias homeopáticas","contexto":"En un titular de registros sanitarios que opera en Colombia, el equipo analiza este caso de unidad 1. Fundamentos y marco normativo de los medicamentos homeopáticos en Colombia: Homeolab (ficticia) tiene en su portafolio (datos simulados): (1) gránulos de una sola cepa en diluciones 6, 12 y 30 CH; (2) gotas que combinan cinco cepas para «el resfriado»; (3) preparados para pacientes según fórmula médica en su farmacia; (4) un producto importado de una cepa no incluida en ninguna farmacopea oficial. La pregunta que decide esta clase es: Una farmacia homeopática prepara un medicamento para un paciente según la fórmula de su médico. ¿Qué análisis es correcto sobre su régimen?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Es un preparado magistral, regido por el Decreto 1737 de 2005, que no requiere registro sanitario.","correcta":true,"retro":"Correcto. Con sus condiciones de preparación."},{"texto":"Requiere registro sanitario completo antes de entregarse al paciente, como cualquier producto industrial.","correcta":false,"retro":"Los magistrales no se registran."},{"texto":"Está prohibido, porque solo los laboratorios pueden preparar medicamentos homeopáticos.","correcta":false,"retro":"Las farmacias pueden preparar magistrales."},{"texto":"Se rige por el Decreto 677 de 1995 como un medicamento de síntesis química.","correcta":false,"retro":"Tiene su régimen propio."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 04. Cómo impactan los Decretos 334 de 2022 y 1474 de 2023 al régimen homeopático
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Cómo impactan los Decretos 334 de 2022 y 1474 de 2023 al régimen homeopático$t$
     AND m.title = $u$Unidad 1. Fundamentos y marco normativo de los medicamentos homeopáticos en Colombia$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Cómo impactan los Decretos 334 de 2022 y 1474 de 2023 al régimen homeopático$t$, $u$Unidad 1. Fundamentos y marco normativo de los medicamentos homeopáticos en Colombia$u$;
