    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 10. Cepas no farmacopeicas: requisitos del Decreto 1861 de 2006
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Cepas no farmacopeicas: requisitos del Decreto 1861 de 2006$t$
     AND m.title = $u$Unidad 2. Calidad: farmacopeas, cepas y Buenas Prácticas de Manufactura homeopáticas$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Cepas no farmacopeicas: requisitos del Decreto 1861 de 2006$t$, $u$Unidad 2. Calidad: farmacopeas, cepas y Buenas Prácticas de Manufactura homeopáticas$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Cepas no farmacopeicas: requisitos del Decreto 1861 de 2006","texto":"En un titular de registros sanitarios que opera en Colombia, mercadeo quiere lanzar una pieza con una indicación que no está en el registro. Lo que está en juego es el criterio de cepas no farmacopeicas: requisitos del Decreto 1861 de 2006. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar cepas no farmacopeicas: requisitos del Decreto 1861 de 2006 con tus propias palabras y reconocer por qué importa en curso de Regulación de Medicamentos Homeopáticos.","Relacionar cepas no farmacopeicas: requisitos del Decreto 1861 de 2006 con unidad 2. Calidad: farmacopeas, cepas y Buenas Prácticas de Manufactura homeopáticas y con las decisiones de el profesional de asuntos regulatorios.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar cepas no farmacopeicas: requisitos del Decreto 1861 de 2006 y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Interpreta los requisitos para cepas o tinturas no incluidas en farmacopeas oficiales y el papel de la Sala Especializada de Medicamentos Homeopáticos (SEMH)."},{"icono":"ShieldCheck","termino":"Registro sanitario","definicion":"El acto administrativo que autoriza fabricar, importar, envasar o comercializar un producto con unas condiciones aprobadas. Sin él, la operación no es legal."},{"icono":"FileCheck","termino":"Expediente","definicion":"El conjunto ordenado de documentos técnicos, legales y de calidad con el que se demuestra que un producto cumple el régimen aplicable."},{"icono":"Network","termino":"Requisito","definicion":"La condición que la norma exige para radicar, mantener o modificar una autorización sanitaria. Se verifica en la fuente oficial, no de memoria."},{"icono":"ClipboardCheck","termino":"Acto administrativo","definicion":"La decisión de la autoridad que concede, niega, modifica o retira una autorización. Tiene efectos jurídicos y un camino de recursos."},{"icono":"RefreshCw","termino":"Vigilancia sanitaria","definicion":"La facultad de la autoridad para inspeccionar, requerir información, adoptar medidas de seguridad y sancionar."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un titular de registros sanitarios que opera en Colombia, cepas no farmacopeicas: requisitos del Decreto 1861 de 2006 aparece en medio de una decisión que no admite improvisación: mercadeo quiere lanzar una pieza con una indicación que no está en el registro. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 2. Calidad: farmacopeas, cepas y Buenas Prácticas de Manufactura homeopáticas. El objetivo del curso es claro: Que el químico farmacéutico clasifique, registre, mantenga y comunique medicamentos homeopáticos en Colombia conforme a la normativa vigente (Decretos 3554/2004, 1737/2005, 1861/2006, 334/2022 y 1474/2023; Resoluciones 4594/2007, 3665/2009 y 1896/2023), con criterio técnico y ético. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Interpreta los requisitos para cepas o tinturas no incluidas en farmacopeas oficiales y el papel de la Sala Especializada de Medicamentos Homeopáticos (SEMH).","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en registro sanitario y en expediente, no en la intuición.","La clase pertenece a unidad 2. Calidad: farmacopeas, cepas y Buenas Prácticas de Manufactura homeopáticas y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Plan de acción para la visita de BPM.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar cepas no farmacopeicas: requisitos del Decreto 1861 de 2006, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Clasifica cada hallazgo como crítico, mayor o menor, y justifica. Evidencia que debe quedar: Registro del paso.","Propón acciones correctivas y preventivas para cada uno. Evidencia que debe quedar: Registro del paso.","Asigna responsables y fechas antes de la visita. Evidencia que debe quedar: Registro del paso.","Prioriza el plan según el riesgo para el producto. Evidencia que debe quedar: Registro del paso.","Define cómo demostrarás el cierre de cada acción. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: radicar un expediente incompleto Corrección: la autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento.","Error: confundir registro sanitario con certificado de BPM Corrección: son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas.","Error: improvisar la respuesta a un requerimiento Corrección: cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar cepas no farmacopeicas: requisitos del Decreto 1861 de 2006 en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"]}],"errores":[{"error":"Citar una norma derogada","correccion":"Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."},{"error":"Radicar un expediente incompleto","correccion":"La autoridad no completa lo que falta por el solicitante: el requerimiento cuesta tiempo y puede terminar en desistimiento."},{"error":"Tratar la modificación como un trámite menor","correccion":"Un cambio no notificado puede dejar el producto fuera de las condiciones aprobadas."},{"error":"Confundir registro sanitario con certificado de BPM","correccion":"Son controles distintos: uno autoriza el producto; el otro demuestra que la planta cumple las buenas prácticas."},{"error":"Improvisar la respuesta a un requerimiento","correccion":"Cada respuesta debe contestar exactamente lo pedido, con evidencia y dentro del plazo."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Cepas no farmacopeicas: requisitos del Decreto 1861 de 2006»?","respuesta":"Interpreta los requisitos para cepas o tinturas no incluidas en farmacopeas oficiales y el papel de la Sala Especializada de Medicamentos Homeopáticos (SEMH)."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Plan de acción para la visita de BPM.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Citar una norma derogada Antes de usar un artículo, confirma su vigencia en el normograma oficial y revisa modificaciones posteriores."}],"resumen":["Cepas no farmacopeicas: requisitos del Decreto 1861 de 2006 se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 2. Calidad: farmacopeas, cepas y Buenas Prácticas de Manufactura homeopáticas.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué documento verificarías primero y dónde confirmarías que el requisito sigue vigente?"],"referencias":[{"cita":"[Página web] Decreto 1861 de 2006 – Por el cual se modifica y adiciona el Decreto 3554 de 2004. Normograma INVIMA (ES)","url":"https://normograma.invima.gov.co/normograma/compilacion/docs/decreto_1861_2006.htm"},{"cita":"Acta No. 08 de 2025 – Comisión Revisora, Sala Especializada de Medicamentos Homeopáticos (SEMH). INVIMA – Comisión Revisora (ES)","url":"https://www.invima.gov.co/biblioteca/acta_no_08_-2025_semhpdf"},{"cita":"INVIMA. Portal institucional y normograma.","url":"https://www.invima.gov.co/"},{"cita":"Presidencia de la República. Decreto 677 de 1995: régimen de registros sanitarios y control de calidad de medicamentos.","url":"https://www.funcionpublica.gov.co/eva/gestornormativo/norma_pdf.php?i=9751"},{"cita":"Ministerio de Salud y Protección Social. Normatividad en salud.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Paginas/default.aspx"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente cepas no farmacopeicas: requisitos del Decreto 1861 de 2006 en un titular de registros sanitarios que opera en Colombia.","alt":"Ilustración de cepas no farmacopeicas: requisitos del Decreto 1861 de 2006"}],"keywords":["curso","regulación","medicamentos","homeopáticos","cepas","farmacopeicas","requisitos","decreto","unidad","calidad","farmacopeas","buenas"],"mapa":{"centro":"Cepas no farmacopeicas: requisitos del Decreto 1861 de 2006","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Asuntos regulatorios — productos especiales","Unidad 2. Calidad: farmacopeas, cepas y Buenas Prácticas de Manufactura homeopáticas","Registro sanitario"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Citar una norma derogada","Radicar un expediente incompleto","Tratar la modificación como un trámite menor"]}]},"proceso":{"titulo":"Cómo se aplica: Preparación de la visita de certificación de BPM homeopáticas","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Clasifica cada hallazgo como crítico, mayor o menor, y justifica.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Propón acciones correctivas y preventivas para cada uno.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Asigna responsables y fechas antes de la visita.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Prioriza el plan según el riesgo para el producto.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Define cómo demostrarás el cierre de cada acción.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Preparación de la visita de certificación de BPM homeopáticas","contexto":"Laboratorio Similia (ficticio) recibirá la visita de certificación de BPM homeopáticas en tres meses (datos simulados). La autoinspección encontró: tinturas madre sin certificado de identidad; un solo cuarto para todas las dinamizaciones; registros de lote incompletos; y un proveedor de lactosa sin calificar.","pregunta":"¿Qué decisión demuestra que entendiste cepas no farmacopeicas: requisitos del Decreto 1861 de 2006?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
