  END IF;

  -- 17. Evaluación de utilidad terapéutica y la Sala Especializada de Medicamentos Homeopáticos
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Evaluación de utilidad terapéutica y la Sala Especializada de Medicamentos Homeopáticos$t$
     AND m.title = $u$Unidad 3. Registro sanitario de medicamentos homeopáticos$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Evaluación de utilidad terapéutica y la Sala Especializada de Medicamentos Homeopáticos$t$, $u$Unidad 3. Registro sanitario de medicamentos homeopáticos$u$;
